//AWVALID MUX 
reg [SLAVE_NUM-1:0]AWVALIDsi2mi; 


//MUX TYPE 00 was Generated 
always @(CtlData2writech  or 
         AWVALIDm2si  )
begin

    if(CtlData2writech [SLAVE_WID]) //MUX enalbe bit
    begin
        case(CtlData2writech [SLAVE_WID-1:0])
        //synopsys parallel_case full_case
            3'd0:   
            begin
                 AWVALIDsi2mi[0] <= AWVALIDm2si ;
                 AWVALIDsi2mi[3] <= 1'b0;
                 AWVALIDsi2mi[4] <= 1'b0;
                 AWVALIDsi2mi[5] <= 1'b0;
            end
            3'd3:   
            begin
                 AWVALIDsi2mi[0] <= 1'b0;
                 AWVALIDsi2mi[3] <= AWVALIDm2si ;
                 AWVALIDsi2mi[4] <= 1'b0;
                 AWVALIDsi2mi[5] <= 1'b0;
            end
            3'd4:   
            begin
                 AWVALIDsi2mi[0] <= 1'b0;
                 AWVALIDsi2mi[3] <= 1'b0;
                 AWVALIDsi2mi[4] <= AWVALIDm2si ;
                 AWVALIDsi2mi[5] <= 1'b0;
            end
            default:
            begin
                AWVALIDsi2mi[0] <= 1'b0;
                AWVALIDsi2mi[3] <= 1'b0;
                AWVALIDsi2mi[4] <= 1'b0;
                AWVALIDsi2mi[5] <= AWVALIDm2si ;
            end
        endcase
    end
    else
    begin
        AWVALIDsi2mi[0] <= 1'b0;
        AWVALIDsi2mi[3] <= 1'b0;
        AWVALIDsi2mi[4] <= 1'b0;
        AWVALIDsi2mi[5] <= 1'b0;
