            //synopsys parallel_case full_case
            3'd0: AWREADYsi2m <= AWREADYmi2si[0];
            3'd3: AWREADYsi2m <= AWREADYmi2si[3];
            3'd4: AWREADYsi2m <= AWREADYmi2si[4];
            3'd5: AWREADYsi2m <= AWREADYmi2si[5];
            default:
                AWREADYsi2m <= 1'b0;
        endcase
    end
    else
        AWREADYsi2m <= 1'b0;
end

