//Slave Number 0
wire Slave0MAX0En = (AWADDRm2si >= 32'h60000000) ? 1'b1:1'b0;
wire Slave0MIN0En = (32'h70000000 >  AWADDRm2si)  ? 1'b1:1'b0;
wire Slave0_0En = Slave0MAX0En & Slave0MIN0En;

//Slave Number 3
wire Slave3MAX0En = (AWADDRm2si >= 32'h0) ? 1'b1:1'b0;
