wire Slave4_0En = Slave4MAX0En & Slave4MIN0En;


//Slave Number 0
wire Slave0MAX1En = (AWADDRm2si >= 32'h60000000) ? 1'b1:1'b0;
wire Slave0MIN1En = (32'h70000000 >  AWADDRm2si)  ? 1'b1:1'b0;
wire Slave0_1En = Slave0MAX1En & Slave0MIN1En;

//Selection mux
wire Slave0En = (SelMAP1) ? Slave0_1En : Slave0_0En;

//Slave Number 3
wire Slave3MAX1En = (AWADDRm2si >= 32'h20000000) ? 1'b1:1'b0;
wire Slave3MIN1En = (32'h40000000 >  AWADDRm2si)  ? 1'b1:1'b0;
wire Slave3_1En = Slave3MAX1En & Slave3MIN1En;

//Selection mux
wire Slave3En = (SelMAP1) ? Slave3_1En : Slave3_0En;

//Slave Number 4
wire Slave4MAX1En = (AWADDRm2si >= 32'h0) ? 1'b1:1'b0;
wire Slave4MIN1En = (32'h10000000 >  AWADDRm2si)  ? 1'b1:1'b0;
wire Slave4_1En = Slave4MAX1En & Slave4MIN1En;

//Selection mux
wire Slave4En = (SelMAP1) ? Slave4_1En : Slave4_0En;



wire Slave5En = 
                !Slave0En &
                !Slave3En &
                !Slave4En ;

always @(
         Slave0En or
         Slave3En or
         Slave4En or
         Slave5En  
        )
begin
    case(1'b1) //synopsys parallel_case
        Slave0En:   SlaveNum <= 3'd0;
        Slave3En:   SlaveNum <= 3'd3;
        Slave4En:   SlaveNum <= 3'd4;
        Slave5En:   SlaveNum <= 3'd5;
        default:   SlaveNum <= {3{1'd0}};
    endcase
end

