reg   BVALIDsi2m;  
reg   [SLAVE_NUM-1:0]   BREADYsi2mi;    


//Arbiter
//_______________________________________________________________
reg   [SLAVE_WID-1:0] CtlData2resch;
//Response Arbiter
//Arbiter was Generated TYPE00
reg   EnArbiter;

always @(
         BVALIDmi2si or
         CtlData2resch
        )
begin
    case(CtlData2resch)
        //synopsys parallel_case full_case
        3'd0:    EnArbiter <= BVALIDmi2si[0];
        3'd3:    EnArbiter <= BVALIDmi2si[3];
        3'd4:    EnArbiter <= BVALIDmi2si[4];
        3'd5:    EnArbiter <= BVALIDmi2si[5];
        default: EnArbiter <= 1'b0;
    endcase
end

always  @(posedge ACLK or negedge ARESETn)
begin
    if(!ARESETn)
    begin
        CtlData2resch <= 0;
    end
    else if(!EnArbiter)
    begin
          if(BVALIDmi2si[0]) CtlData2resch <= 3'd0;
          else if(BVALIDmi2si[3]) CtlData2resch <= 3'd3;
          else if(BVALIDmi2si[4]) CtlData2resch <= 3'd4;
          else if(BVALIDmi2si[5]) CtlData2resch <= 3'd5;
    end
end


//Demux reaponse channel
//MUX TYPE 01 was Generated 
always @(CtlData2resch  or 
         BREADYm2si  )
begin

   case(CtlData2resch )
   //synopsys parallel_case full_case
        3'd0:   
            begin
                 BREADYsi2mi[0] <= BREADYm2si ;
                 BREADYsi2mi[3] <= 1'b0;
                 BREADYsi2mi[4] <= 1'b0;
                 BREADYsi2mi[5] <= 1'b0;
            end
        3'd3:   
            begin
                 BREADYsi2mi[0] <= 1'b0;
                 BREADYsi2mi[3] <= BREADYm2si ;
                 BREADYsi2mi[4] <= 1'b0;
                 BREADYsi2mi[5] <= 1'b0;
            end
        3'd4:   
            begin
                 BREADYsi2mi[0] <= 1'b0;
                 BREADYsi2mi[3] <= 1'b0;
                 BREADYsi2mi[4] <= BREADYm2si ;
                 BREADYsi2mi[5] <= 1'b0;
            end
         default:
            begin
                BREADYsi2mi[0] <= 1'b0;
                BREADYsi2mi[3] <= 1'b0;
                BREADYsi2mi[4] <= 1'b0;
                BREADYsi2mi[5] <= BREADYm2si ;
            end
   endcase
end

//Demux reaponse channel

always @(
         BIDmi02si or
         BIDmi32si or
         BIDmi42si or
         BIDmi52si or
        CtlData2resch 
        )
begin
    case(CtlData2resch)
        3'd0: BIDsi2m      <= BIDmi02si;     
        3'd3: BIDsi2m      <= BIDmi32si;     
        3'd4: BIDsi2m      <= BIDmi42si;     
        3'd5: BIDsi2m      <= BIDmi52si;     
//Syn Warning
        default:       BIDsi2m      <= 0;
    endcase
end

always @(
         BRESPmi02si   or
         BRESPmi32si   or
         BRESPmi42si   or
         BRESPmi52si   or
         CtlData2resch 
        )
begin
    case(CtlData2resch)
        3'd0: BRESPsi2m   <= BRESPmi02si;     
        3'd3: BRESPsi2m   <= BRESPmi32si;     
        3'd4: BRESPsi2m   <= BRESPmi42si;     
        3'd5: BRESPsi2m   <= BRESPmi52si;     
//Syn Warning
        default:       BRESPsi2m   <= 0;
    endcase
end


always @(CtlData2resch or
         BVALIDmi2si    
        )
begin
    case(CtlData2resch)
        3'd0: BVALIDsi2m   <= BVALIDmi2si[0];     
        3'd3: BVALIDsi2m   <= BVALIDmi2si[3];     
        3'd4: BVALIDsi2m   <= BVALIDmi2si[4];     
        3'd5: BVALIDsi2m   <= BVALIDmi2si[5];     
//Syn Warning
        default:       BVALIDsi2m   <= 0;
    endcase
end

WRCH_DMA2D_PermitCtl
    U0PermitCtl(

    .ACLK       (ACLK)      ,
    .ARESETn    (ARESETn)   ,
    .SlaveNum   (SlaveNum)  ,

    .SID       (AWIDm2si),
    .AREADY    (AWREADYsi2m),
    .AVALID    (AWVALIDm2si),    

    .WID       (WIDm2si),
    .WREADY    (WREADYsi2m),
    .WVALID    (WVALIDm2si),
    .WLAST     (WLASTm2si),
    /*
    .WREADY     (1'b0),
    .WVALID     (1'b0),
    .WLAST      (1'b0),
    */

    .LID       (BIDsi2m),
    .LAST      (BVALIDsi2m),
    .READY     (BREADYm2si),
    .RVALID    (1'b1),

    .CtlData2datach  (CtlData2datach),
    .CtlData2writech (CtlData2writech) 

    );
endmodule
//Code_END
